GLOSSARY = [
    ["Access token", "Short-lived credential presented on each request to a protected route"],
    ["Attestation", "Statement by an authenticator about its make and model, verified against trust anchors"],
    ["Audit sink", "Application-supplied object that receives Ninsho's security events"],
    ["Bearer token", "Token that grants access to whoever presents it"],
    ["BroadcastChannel", "Browser API for messages between same-origin tabs"],
    ["Clock tolerance", "Allowance for clock differences when checking expiry"],
    ["Deny-list", "Store of revoked token identifiers checked during verification"],
    ["DPoP", "Proof that the sender holds the private key a token is bound to (RFC 9449)"],
    ["Fail-closed / fail-open", "Refusing / admitting a request when the state needed to decide is unavailable"],
    ["Family", "All refresh tokens descended from one session by rotation"],
    ["Grace window", "Short period in which a just-rotated refresh token resolves to its replacement"],
    ["Guard", "Middleware that answers an authorization question and refuses with 403"],
    ["JWK thumbprint", "Hash of a public key's required members (RFC 7638) used to bind a token"],
    ["Opaque token", "Random token whose meaning is held only on the server"],
    ["PAE", "Pre-authentication encoding that binds PASETO's header, payload and footer"],
    ["Principal", "Identity passed to createSession(): user id, roles, scopes, optional tenant"],
    ["Refresh token", "Longer-lived credential exchanged for a new access token"],
    ["Reuse detection", "Recognising that a rotated refresh token was presented again"],
    ["Revocation marker", "Store key written first during revocation so that concurrent issuance sees it"],
    ["Rotation", "Replacing a refresh token with a new one each time it is used"],
    ["Store contract", "The interface every Ninsho store must satisfy, including atomic take and set-if-absent"],
    ["Tombstone", "Record that a refresh token was consumed, used to detect reuse"],
    ["Trust boundary", "Point where data crosses from a less trusted to a more trusted context"],
]
